// four jobs whose seller has a calibrated record → one item each. No state is built here: the judge builds each
// evidence pack from the job's own facts (schemas/GRADEABLE.md).
return ($input.first().json.jobs || []).filter((j) => j.record && j.record.calibrated).slice(0, 4).map((j) => ({ json: { ...j, chainId: j.chainId ?? 8453 } }));

// ── canonical VERDICT (taifoon.verdict.v1) from a decision record — the same mapping as schemas/src/from/judge.ts
// fromDecision, inlined because an n8n code node cannot import the schemas package. workflows/test.mjs runs this node
// and compares its output with fromDecision field by field.
const SITE = 'https://www.taifoon.io';
const isHash = (s) => typeof s === 'string' && /^0x[0-9a-fA-F]{64}$/.test(s);
const chainAnchor = (chain_id, tx, what, x = {}) => ({ kind: 'chain', chain_id, tx: tx.toLowerCase(), block: x.block ?? null, ts: x.ts ?? null, log_index: x.log_index ?? null, contract: x.contract ? x.contract.toLowerCase() : null, what });
function jobKeyOf(subject) {
  const ref = String(subject && subject.ref || ''), chain = Number(subject && subject.chainId) || 8453;
  if (/^hs_[0-9a-f]{24}$/.test(ref)) return 'hs:' + ref;
  if (/^([a-z][a-z0-9-]{0,31}):([1-9][0-9]{0,9}):([0-9]{1,78})$/.test(ref)) return ref;
  if (/^0x[0-9a-fA-F]{64}$/.test(ref)) return 'hook:' + chain + ':' + ref.toLowerCase();
  if (/^[0-9]{1,78}$/.test(ref)) return /^[0-9]{10,12}$/.test(ref) && BigInt(ref) >= 1000000001n ? 'memo-acp:8453:' + ref : 'erc8183:' + chain + ':' + ref;
  return null;
}
function verdictFromDecision(d, composed) {
  const rubric = /RUBRIC_v1 compose · rubric (0x[0-9a-f]{64})/.exec(String(d.note ?? ''));
  const anchors = [];
  if (d.anchor && isHash(d.anchor.tx)) anchors.push(chainAnchor(Number(d.anchor.chain), d.anchor.tx, `JevDecisionLog.record${d.anchor.index != null ? ` (decision index ${d.anchor.index})` : ''} · status ${d.anchor.status}`, { block: d.anchor.block ?? null, contract: d.anchor.contract ?? null }));
  anchors.push({ kind: 'offchain', store: 'coordd:decisions', key: String(d.id), digest: isHash(d.digest) ? d.digest.toLowerCase() : null, anchored_by: anchors[0] && anchors[0].kind === 'chain' ? anchors[0] : null, what: 'the decision record; digest = sha256(canonicalDecision)' });
  return {
    schema: 'taifoon.verdict.v1', decision_id: String(d.id), version: d.v, kind: d.kind,
    subject: { chain_id: Number(d.subject && d.subject.chainId), at: d.subject && d.subject.at ? String(d.subject.at).toLowerCase() : null, ref: String(d.subject && d.subject.ref), label: (d.subject && d.subject.label) ?? null },
    subject_id: String(d.subject_id).toLowerCase(), subject_job_key: jobKeyOf(d.subject), digest: String(d.digest).toLowerCase(),
    input_digest: isHash(d.input_digest) ? d.input_digest.toLowerCase() : null, answers_digest: isHash(d.answers_digest) ? d.answers_digest.toLowerCase() : null,
    answers: (d.answers || []).map((a) => ({ id: String(a.id), question: a.question ?? null, options: a.options ?? null, value: String(a.value), probabilities: a.probabilities ?? {}, confidence: Number(a.confidence) })),
    confidence_bps: d.confidence_bps, model: d.model ?? null, answers_source: d.answers_source ?? 'layer',
    rubric: rubric ? { version: 'RUBRIC_v1', hash: rubric[1] } : null,
    composed: composed ? { verdict: composed.verdict, auto: Boolean(composed.auto), forced: composed.forced ?? null, reasons: (composed.reasons || []).map(String), receipt_hash: isHash(composed.receiptHash) ? composed.receiptHash.toLowerCase() : null } : null,
    anchors, source: { kind: 'decision', url: d.uri ?? `${SITE}/v1/judge/decisions/${d.id}`, read_at: Math.floor(Date.now() / 1000) },
  };
}
// the GradeStampRegistry verdict code (1 delivered_as_specified · 2 delivered_with_defects · 3 not_delivered · 4 cannot_determine)
const STAMP_CODE = { delivered_as_specified: 1, delivered_with_defects: 2, not_delivered: 3, cannot_determine: 4 };
function stampCodeOf(v) {
  if (v.composed) return v.composed.verdict === 'complete' ? 1 : v.composed.verdict === 'reject' ? 2 : 4;
  const ref = (v.answers || []).find((a) => STAMP_CODE[a.value]);
  return ref ? STAMP_CODE[ref.value] : 4;
}
// the stamp transaction(s) the devnet signer mined → appended to the verdict's anchors
const stampAnchors = (sent, chainId) => (sent || []).filter((s) => isHash(s.tx) && s.status === 'success').map((s) => chainAnchor(chainId, s.tx, 'GradeStampRegistry.stamp (' + (s.action || 'stamp') + ')', { block: s.block ?? null, contract: s.to ?? null }));

// the recorded decision → the canonical VERDICT, composed from this run's receipt
const a = $json;
if (!a.decision || !a.decision.id) throw new Error('judge answers returned no decision: ' + JSON.stringify(a).slice(0, 300));
const d = (await this.helpers.httpRequest({ method: 'GET', url: SITE + '/v1/judge/decisions/' + a.decision.id, json: true })).decision;
const v = verdictFromDecision(d, a.receipt);
return { json: { ...v, stamp: { code: stampCodeOf(v), mode: 2 } } };

